package client

import (
	"github.com/cloudwego/kitex/internal/client"
	"github.com/cloudwego/kitex/pkg/utils"
)

// UnaryOption is a client option specifically for unary RPC calls.
// It wraps the standard Option type to provide type-safe option categorization.
type UnaryOption struct {
	Option
}

// StreamOption is a client option specifically for streaming RPC calls.
// It wraps the standard Option type to provide type-safe option categorization.
type StreamOption struct {
	Option
}

// TTHeaderStreamingOption is a client option specifically for TTHeader-based streaming.
// It wraps the standard Option type to provide type-safe option categorization.
type TTHeaderStreamingOption struct {
	Option
}

// AsUnaryOption converts a standard Option to a UnaryOption.
// This function is used to explicitly mark an option as suitable for unary RPC calls.
//
// Example:
//   opt := AsUnaryOption(WithTimeout(time.Second))
func AsUnaryOption(opt Option) UnaryOption {
	return UnaryOption{Option: opt}
}

// AsStreamOption converts a standard Option to a StreamOption.
// This function is used to explicitly mark an option as suitable for streaming RPC calls.
//
// Example:
//   opt := AsStreamOption(WithStreamMiddleware(myMiddleware))
func AsStreamOption(opt Option) StreamOption {
	return StreamOption{Option: opt}
}

// AsTTHeaderStreamingOption converts a standard Option to a TTHeaderStreamingOption.
// This function is used to explicitly mark an option as suitable for TTHeader streaming.
//
// Example:
//   opt := AsTTHeaderStreamingOption(WithTTHeaderFrame())
func AsTTHeaderStreamingOption(opt Option) TTHeaderStreamingOption {
	return TTHeaderStreamingOption{Option: opt}
}

// ToOption extracts the underlying Option from a UnaryOption.
func (u UnaryOption) ToOption() Option {
	return u.Option
}

// ToOption extracts the underlying Option from a StreamOption.
func (s StreamOption) ToOption() Option {
	return s.Option
}

// ToOption extracts the underlying Option from a TTHeaderStreamingOption.
func (t TTHeaderStreamingOption) ToOption() Option {
	return t.Option
}

// UnaryOptions is a collection of UnaryOption values.
// It provides a convenient way to group multiple unary-specific options.
type UnaryOptions []UnaryOption

// ToOptions converts a UnaryOptions collection to a slice of standard Options.
func (opts UnaryOptions) ToOptions() []Option {
	result := make([]Option, len(opts))
