const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Handle known individual and composite constants first
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// For composite values with multiple bits set
	// Check individual bits in ascending order of their numeric values
	var parts []string
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "HESSIAN2")
	}
	if tp&TTHeaderStreaming != 0 {
		parts = append(parts, "TTHeaderStreaming")
	}
	if tp&GRPCStreaming != 0 {
		parts = append(parts, "GRPCStreaming")
	}
	if len(parts) > 0 {
		return strings.Join(parts, "|")
	}
	return Unknown
}

func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		// Enhanced error with hex dump for debugging
		if len(buf) > 0 && len(buf) >= 4 {
			first4Bytes := binary.BigEndian.Uint32(buf[:4])
			hexDump := fmt.Sprintf("%x", buf)
			return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w, first4Bytes=%#x, partial data (hex): %s", err, first4Bytes, hexDump)
		} else if len(buf) > 0 {
			hexDump := fmt.Sprintf("%x", buf)
			return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w, partial data (hex): %s", err, hexDump)
		}
		return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w", err)
	}
	return http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
		// valid:    true,
	}, nil
}

